insert into public.site_settings (id, data) values (1, '{"name":"Comunidad Evangélica La Cosecha","shortName":"La Cosecha","denomination":"Asambleas de Dios","city":"Juigalpa, Chontales, Nicaragua","address":"Gasolinera UNO, 3 cuadras al Este, donde fue el restaurante La Cazuelita, Juigalpa, Chontales","phone":"+505 8404 0236","whatsapp":"50584040236","email":"comunidadevangelicalacosecha@gmail.com","motto":"Jehová peleará por nosotros, y nosotros estaremos tranquilos","mottoRef":"Éxodo 14:14","description":"La Comunidad Evangélica La Cosecha es una congregación cristiana ubicada en Juigalpa, Chontales, Nicaragua. Busca compartir el mensaje de Jesucristo, fortalecer la fe, formar discípulos y servir a las personas y familias de la comunidad mediante la enseñanza bíblica, la oración, la comunión y acciones de servicio.","founded":"2025-12-20","pastor":"Pedro Obando","associatePastor":"Fátima González","social":{"facebook":"https://www.facebook.com/profile.php?id=61583287506730","instagram":"https://www.instagram.com/c.e.lacosecha","tiktok":"https://www.tiktok.com/@c_e_lacosecha"},"heroImage":"/images/galeria/hero.jpg","logo":"/logo.png","prayerNote":"Oración y ayuno: de lunes a viernes, entre semana."}'::jsonb) on conflict (id) do nothing;
insert into public.about_sections (id, eyebrow, title, subtitle, body, list, image, position) values ('historia', 'Nuestra historia', 'Una cosecha que comienza', 'Fundada el 20 de diciembre de 2025', 'La Comunidad Evangélica La Cosecha nace en Juigalpa, Chontales, el 20 de diciembre de 2025, bajo la cobertura de las Asambleas de Dios. Desde sus inicios ha buscado ser un hogar espiritual donde las familias conozcan a Jesucristo, crezcan en la Palabra y sirvan a su comunidad.', null, '/images/galeria/historia.jpg', 0) on conflict (id) do nothing;
insert into public.about_sections (id, eyebrow, title, subtitle, body, list, image, position) values ('mision', 'Misión', 'Compartir a Cristo y formar discípulos', 'Nuestro propósito', 'Compartir el mensaje de Jesucristo, fortalecer la fe y formar discípulos que sirvan a las personas y familias de nuestra comunidad mediante la enseñanza bíblica, la oración, la comunión y acciones de servicio.', null, '/images/mision.jpg', 1) on conflict (id) do nothing;
insert into public.about_sections (id, eyebrow, title, subtitle, body, list, image, position) values ('vision', 'Visión', 'Familias transformadas por el amor de Dios', 'Hacia dónde vamos', 'Ser una iglesia que lleve esperanza a Juigalpa y Chontales, levantando líderes y discípulos comprometidos con Cristo, y extendiendo su amor a cada hogar a través del servicio y la Palabra.', null, '/images/vision.jpg', 2) on conflict (id) do nothing;
insert into public.about_sections (id, eyebrow, title, subtitle, body, list, image, position) values ('valores', 'Valores', 'Lo que nos define', 'Principios que guían nuestro caminar', 'Vivimos nuestra fe en comunidad, guiados por principios bíblicos que dan forma a todo lo que hacemos.', array['Fe', 'Amor', 'Servicio', 'Unidad', 'Integridad']::text[], '/images/galeria/valores.jpg', 3) on conflict (id) do nothing;
insert into public.about_sections (id, eyebrow, title, subtitle, body, list, image, position) values ('liderazgo', 'Liderazgo', 'Pastores que sirven', 'Pastor Pedro Obando y Pastora Fátima González', 'La congregación es pastoreada por el Pastor Pedro Obando (pastor general) y la Pastora Fátima González (pastora asociada), quienes junto al equipo ministerial guían, enseñan y acompañan a la iglesia.', null, '/images/galeria/liderazgo.jpg', 4) on conflict (id) do nothing;
insert into public.schedules (id, title, day, time, description, featured) values ('culto-dominical', 'Culto principal', 0, '17:30', 'Celebración dominical para toda la familia.', true) on conflict (id) do nothing;
insert into public.schedules (id, title, day, time, description, featured) values ('escuela-lideres', 'Escuela de líderes', 2, '19:00', 'Formación para los líderes de la iglesia.', false) on conflict (id) do nothing;
insert into public.schedules (id, title, day, time, description, featured) values ('culto-miercoles', 'Culto de entre semana', 3, '18:00', 'Palabra, oración y comunión a mitad de semana.', false) on conflict (id) do nothing;
insert into public.schedules (id, title, day, time, description, featured) values ('discipulado', 'Discipulado', 4, '18:00', 'Acompañamiento para los nuevos en la fe.', false) on conflict (id) do nothing;
insert into public.schedules (id, title, day, time, description, featured) values ('jovenes', 'Generación de Fuego', 5, '18:00', 'Reunión de jóvenes.', false) on conflict (id) do nothing;
insert into public.ministries (id, name, summary, description, leaders, activities, icon, image, position) values ('generacion-de-fuego', 'Generación de Fuego', 'Ministerio de jóvenes: fe, amistad y propósito.', 'Ministerio responsable de los jóvenes de la iglesia. Un espacio para crecer en la fe, compartir en comunidad y descubrir el propósito de Dios para cada vida.', array['Mackferson Sequeira', 'Juan Zambrana', 'Dareska Castilla']::text[], array['Reunión de jóvenes · Viernes 6:00 PM', 'Actividades juveniles']::text[], 'flame', '/images/ministerios/jovenes.jpg', 0) on conflict (id) do nothing;
insert into public.ministries (id, name, summary, description, leaders, activities, icon, image, position) values ('escuela-de-lideres', 'Escuela de Líderes', 'Formación para quienes sirven en la iglesia.', 'Ministerio encargado de enseñar y equipar a los líderes de la iglesia para servir con excelencia y carácter cristiano.', array['Pastor Pedro Obando', 'Pastora Fátima González']::text[], array['Clases · Martes 7:00 PM']::text[], 'book', '/images/ministerios/lideres.jpg', 1) on conflict (id) do nothing;
insert into public.ministries (id, name, summary, description, leaders, activities, icon, image, position) values ('discipulado', 'Discipulado y Formación Bíblica', 'Acompañamos a los nuevos en la fe.', 'Ministerio encargado de acompañar a los nuevos creyentes, enseñándoles los fundamentos de la fe y ayudándoles a crecer en su relación con Dios.', array['Mackferson Sequeira', 'Edwing Márquez']::text[], array['Discipulado · Jueves 6:00 PM']::text[], 'sprout', '/images/ministerios/discipulado.jpg', 2) on conflict (id) do nothing;
insert into public.ministries (id, name, summary, description, leaders, activities, icon, image, position) values ('programa-esperanza', 'Programa Esperanza', 'Amor y servicio a personas en necesidad.', 'El Programa Esperanza es una iniciativa de amor y servicio que brinda apoyo a personas en situación de vulnerabilidad, ofreciéndoles alimento, aseo personal, acompañamiento y la Palabra de Dios. Buscamos restaurar vidas, devolver la dignidad y demostrar el amor de Cristo a quienes más lo necesitan.', array['Pastor Pedro Obando']::text[], array['Entrega de alimentos', 'Aseo personal', 'Acompañamiento']::text[], 'heart', '/images/ministerios/esperanza.jpg', 3) on conflict (id) do nothing;
insert into public.ministries (id, name, summary, description, leaders, activities, icon, image, position) values ('evangelismo', 'Evangelismo y Alcance Comunitario', 'Llevamos esperanza a cada hogar.', 'Busca compartir el mensaje de Jesucristo, llevando esperanza, fe y amor a las familias y personas de nuestra comunidad.', array['David Arana']::text[], array['Jornadas de evangelismo', 'Campañas', 'Servicio comunitario']::text[], 'megaphone', '/images/ministerios/evangelismo.jpg', 4) on conflict (id) do nothing;
insert into public.ministries (id, name, summary, description, leaders, activities, icon, image, position) values ('alabanza', 'Ministerio de Alabanza', 'Adoramos a Dios con música y canto.', 'Tiene como propósito dirigir a la congregación en la adoración a Dios mediante la música y el canto, creando un ambiente de entrega, comunión y exaltación a nuestro Señor Jesucristo.', array['Dareska Castillo']::text[], array['Alabanza en cultos', 'Ensayos']::text[], 'music', '/images/ministerios/alabanza.jpg', 5) on conflict (id) do nothing;
insert into public.ministries (id, name, summary, description, leaders, activities, icon, image, position) values ('intercesion', 'Ministerio de Intercesión', 'Oración constante por la iglesia y la ciudad.', 'Se dedica a la oración constante por la iglesia, sus líderes, las familias y las necesidades de la comunidad, creyendo en el poder de Dios para transformar vidas.', array['Lucía Salazar']::text[], array['Oración y ayuno · lunes a viernes']::text[], 'hands', '/images/ministerios/intercesion.jpg', 6) on conflict (id) do nothing;
insert into public.ministries (id, name, summary, description, leaders, activities, icon, image, position) values ('multimedia', 'Ministerio de Multimedia', 'Tecnología al servicio del mensaje.', 'Se encarga de apoyar las actividades y servicios de la iglesia mediante recursos tecnológicos, proyección, fotografía, video y transmisión en redes sociales, llevando el mensaje de Dios a más personas.', array['Mackferson Sequeira']::text[], array['Proyección', 'Fotografía y video', 'Redes sociales']::text[], 'monitor', '/images/ministerios/multimedia.jpg', 7) on conflict (id) do nothing;
