insert into public.announcements (title, body, date, featured, published) select 'Síguenos en redes sociales', 'Todas nuestras actividades, eventos y anuncios especiales se publican en Facebook, Instagram y TikTok. ¡Síguenos para no perderte nada!', '2026-11-01', true, true where not exists (select 1 from public.announcements where title = 'Síguenos en redes sociales');
insert into public.announcements (title, body, date, featured, published) select 'Células en tu sector', 'Tenemos grupos de crecimiento en diferentes sectores de Juigalpa. Escríbenos por WhatsApp y te conectamos con el más cercano a tu hogar.', '2026-11-01', false, true where not exists (select 1 from public.announcements where title = 'Células en tu sector');
